mapper.select:
SELECT attendance_setup_idempotency_id AS record_id,
       request_digest, state, response_status,
       response_headers_json, response_body_json, created_at
FROM attendance_setup_idempotency
WHERE actor_id = #{actorId}
  AND operation_code = #{operation}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE attendance_setup_idempotency
SET attendance_setup_idempotency_id = #{nextRecordId},
    created_at = #{createdAt}
WHERE attendance_setup_idempotency_id = #{currentRecordId}
  AND request_digest = #{requestDigest}
  AND state = 'STARTED'
  AND created_at <= #{staleBefore}

UPDATE attendance_setup_idempotency
SET state = 'COMPLETED_SUCCESS',
    response_status = #{responseStatus},
    response_headers_json = #{responseHeadersJson},
    response_body_json = #{responseBodyJson},
    completed_at = #{completedAt}
WHERE attendance_setup_idempotency_id = #{recordId}
  AND request_digest = #{requestDigest}
  AND state = 'STARTED'
